import { useEffect, useState } from 'react';
import type { ReactNode, FormEvent } from 'react';
import { Link, Navigate, Route, Routes, useLocation, useNavigate } from 'react-router-dom';
import { useQueryClient } from '@tanstack/react-query';
import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { Activity, AlertTriangle, ArrowLeft, ArrowRight, ArrowUpRight, Banknote, BarChart3, BriefcaseBusiness, Check, ClipboardList, CreditCard, FileText, LayoutDashboard, LogOut, Menu, Package, Plus, Search, Settings, ShieldCheck, ShoppingBag, ShoppingCart, Store, Tags, Trash2, Users, X, Pencil, Eye, CircleCheck, Ban, RotateCcw, SlidersHorizontal, TrendingUp } from 'lucide-react';
import { resetDemo, saveData, EVENT } from '@/services/mock/store';
import { useDemoData } from '@/hooks/use-demo-data';
import { formatBs, formatDate, formatTime } from '@/lib/format';
import type { Categoria, DemoData, Local, MiembroLocal, Producto, Session, StoreRole, Usuario, Venta } from '@/types';
import { newId } from '@/types';

const money = formatBs;
const dateFmt = formatDate;
const timeFmt = formatTime;
const statusText: Record<string,string> = { ACTIVE:'Activo', SUSPENDED:'Suspendido', CLOSED:'Cerrado', STORE_ADMIN:'Administrador', EMPLOYEE:'Empleado', SUPER_ADMIN:'Superadmin', USER:'Usuario' };
type FieldDef = { name: string; label: string; type?: string; required?: boolean; options?: {label:string;value:string}[]; step?:string; min?:number };

function Toast({ text, onClose }: {text:string;onClose:()=>void}) {
  useEffect(()=>{ const t=window.setTimeout(onClose,3200); return ()=>window.clearTimeout(t); },[onClose]);
  return <div data-testid="status-toast" className="fixed bottom-5 right-5 z-[80] flex max-w-sm items-center gap-3 rounded-xl bg-slate-900 px-4 py-3 text-sm font-medium text-white shadow-xl animate-rise"><CircleCheck size={18} className="shrink-0 text-emerald-400"/>{text}<button aria-label="Cerrar aviso" onClick={onClose} className="ml-2 text-white/60"><X size={16}/></button></div>;
}
function Badge({children,tone='neutral'}:{children:ReactNode;tone?:string}) {
  const classes:Record<string,string>={neutral:'bg-slate-100 text-slate-600',green:'bg-emerald-50 text-emerald-700',amber:'bg-amber-50 text-amber-700',red:'bg-red-50 text-red-700',indigo:'bg-indigo-50 text-indigo-700'};
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-semibold ${classes[tone]||classes.neutral}`}>{children}</span>;
}
function Metric({label,value,meta,icon:Icon,tone='indigo',trend}:{label:string;value:string;meta:string;icon:typeof Store;tone?:string;trend?:string}) {
  const colors:Record<string,string>={indigo:'bg-indigo-50 text-indigo-600',green:'bg-emerald-50 text-emerald-700',amber:'bg-amber-50 text-amber-700',blue:'bg-sky-50 text-sky-700'};
  return <div data-testid={`card-metric-${label.toLowerCase().replaceAll(' ','-')}`} className="mn-card p-5"><div className="flex items-start justify-between"><span className={`grid h-10 w-10 place-items-center rounded-xl ${colors[tone]}`}><Icon size={19}/></span>{trend&&<span className="flex items-center gap-1 text-xs font-semibold text-emerald-700"><ArrowUpRight size={14}/>{trend}</span>}</div><p className="mt-5 text-sm font-medium text-slate-500">{label}</p><p data-testid={`text-metric-${label.toLowerCase().replaceAll(' ','-')}`} className="mt-1 font-[Manrope] text-2xl font-extrabold tracking-tight text-slate-900">{value}</p><p className="mt-1 text-xs text-slate-400">{meta}</p></div>;
}
function HeaderTitle({title,subtitle,action}:{title:string;subtitle:string;action?:ReactNode}) {
  return <div className="mb-6 flex flex-wrap items-end justify-between gap-4"><div><div className="mb-1 text-xs font-semibold uppercase tracking-[.13em] text-indigo-600">Mi Negocio <span className="text-slate-300">/</span> Operaciones</div><h1 data-testid="text-page-title" className="font-[Manrope] text-[26px] font-extrabold tracking-tight text-slate-900">{title}</h1><p className="mt-1 text-sm text-slate-500">{subtitle}</p></div>{action}</div>;
}
function Empty({title,body,action}:{title:string;body:string;action?:ReactNode}) {
  return <div className="flex min-h-56 flex-col items-center justify-center px-5 text-center"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-indigo-50 text-indigo-600"><ClipboardList size={22}/></span><h3 className="mt-4 font-bold text-slate-800">{title}</h3><p className="mt-1 max-w-sm text-sm text-slate-500">{body}</p>{action&&<div className="mt-4">{action}</div>}</div>;
}
function Modal({title,children,onClose}:{title:string;children:ReactNode;onClose:()=>void}) {
  return <div className="fixed inset-0 z-50 flex items-end justify-center bg-slate-950/40 p-0 backdrop-blur-[2px] sm:items-center sm:p-5" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><section className="max-h-[92dvh] w-full max-w-lg overflow-y-auto rounded-t-2xl bg-white p-5 shadow-2xl sm:rounded-2xl sm:p-6 animate-rise"><div className="mb-5 flex items-center justify-between"><h2 className="font-[Manrope] text-lg font-extrabold">{title}</h2><button data-testid="button-close-dialog" onClick={onClose} className="grid h-8 w-8 place-items-center rounded-lg text-slate-400 hover:bg-slate-100"><X size={18}/></button></div>{children}</section></div>;
}
function Editor({title,fields,initial,onClose,onSubmit,submitText='Guardar cambios'}:{title:string;fields:FieldDef[];initial?:object;onClose:()=>void;onSubmit:(values:Record<string,string>)=>Promise<void>|void;submitText?:string}) {
  const [busy,setBusy]=useState(false); const [error,setError]=useState('');
  const initialValues=initial as Record<string,unknown>|undefined;
  const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setError('');const form=new FormData(e.currentTarget);const values=Object.fromEntries(form.entries()) as Record<string,string>; if(fields.some(f=>f.required&&!values[f.name]?.trim())){setError('Completa todos los campos obligatorios.');return;} setBusy(true);try{await onSubmit(values);onClose();}catch(err){setError(err instanceof Error?err.message:'No se pudo guardar. Intenta de nuevo.');}finally{setBusy(false);}};
  return <Modal title={title} onClose={onClose}><form onSubmit={submit} className="space-y-4">{fields.map(f=><div key={f.name}><label className="mn-label" htmlFor={`field-${f.name}`}>{f.label}{f.required?' *':''}</label>{f.options?<select id={`field-${f.name}`} data-testid={`input-${f.name}`} name={f.name} className="mn-input" defaultValue={String(initialValues?.[f.name]??'')}>{f.options.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select>:<input id={`field-${f.name}`} data-testid={`input-${f.name}`} name={f.name} type={f.type||'text'} step={f.step} min={f.min} required={f.required} defaultValue={initialValues?.[f.name]===undefined?'':String(initialValues[f.name])} className="mn-input" />}</div>)}{error&&<p data-testid="text-form-error" className="rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700">{error}</p>}<div className="flex justify-end gap-2 pt-2"><button type="button" onClick={onClose} className="mn-btn mn-btn-secondary">Cancelar</button><button data-testid="button-save" disabled={busy} className="mn-btn mn-btn-primary">{busy?'Guardando…':submitText}</button></div></form></Modal>;
}
function Table({headers,children,empty}:{headers:string[];children:ReactNode;empty?:boolean}) {
  if(empty)return <Empty title="No encontramos resultados" body="Prueba con otra búsqueda o ajusta los filtros." />;
  return <div className="overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead><tr className="border-b border-slate-100 bg-slate-50/70">{headers.map(h=><th key={h} className="px-4 py-3 text-[11px] font-bold uppercase tracking-wider text-slate-500">{h}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{children}</tbody></table></div>;
}
function SearchTools({value,onChange,placeholder='Buscar…',children}:{value:string;onChange:(v:string)=>void;placeholder?:string;children?:ReactNode}) {
  return <div className="mb-4 flex flex-wrap items-center gap-2"><div className="relative min-w-[210px] flex-1 sm:max-w-sm"><Search size={16} className="absolute left-3 top-3 text-slate-400"/><input data-testid="input-search" value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} className="mn-input pl-9"/></div>{children}</div>;
}
function ActionButton({label,onClick,icon:Icon,variant='secondary',id}:{label:string;onClick:()=>void;icon:typeof Pencil;variant?:string;id?:string}) {
  return <button type="button" title={label} aria-label={label} data-testid={`button-${label.toLowerCase().replaceAll(' ','-')}${id?`-${id}`:''}`} onClick={onClick} className={`inline-flex h-8 w-8 items-center justify-center rounded-lg transition ${variant==='danger'?'text-red-600 hover:bg-red-50':'text-slate-500 hover:bg-indigo-50 hover:text-indigo-700'}`}><Icon size={16}/></button>;
}

type NavGroup={label:string;links:[string,string,typeof LayoutDashboard][]};
const allNav:NavGroup[] = [
  { label:'Vista general', links:[['/app/dashboard','Resumen',LayoutDashboard],['/app/sales/new','Nueva venta',ShoppingCart]] },
  { label:'Tu negocio', links:[['/app/products','Productos',Package],['/app/categories','Categorías',Tags],['/app/inventory','Inventario',SlidersHorizontal],['/app/sales','Ventas',CreditCard]] },
  { label:'Equipo', links:[['/app/employees','Empleados',Users],['/app/settings','Configuración',Settings]] },
];
const adminNav:NavGroup[] = [
  { label:'Plataforma', links:[['/admin/dashboard','Resumen global',LayoutDashboard],['/admin/stores','Locales',Store],['/admin/users','Usuarios',Users]] },
];

export function Workspace({session,setSession}:{session:Session;setSession:(s:Session|null)=>void}) {
  const queryClient=useQueryClient(); const navigate=useNavigate(); const {pathname:location}=useLocation();
  const {data,isLoading,isError,refetch}=useDemoData();
  const [toast,setToast]=useState(''); const [mobileOpen,setMobileOpen]=useState(false);
  const announce=(message:string)=>setToast(message);
  const currentStore=data?.stores.find(s=>s.id===session.storeId);
  const currentUser=data?.users.find(u=>u.id===session.userId);
  const isSuper=session.role==='SUPER_ADMIN'; const isEmployee=session.role==='EMPLOYEE';
  const sessionValid=!data||Boolean(currentUser?.is_active&&(isSuper?currentUser.platform_role==='SUPER_ADMIN':data.memberships.some(m=>m.user_id===session.userId&&m.store_id===session.storeId&&m.role===session.role&&m.is_active)));
  const commit=async(fn:(draft:DemoData)=>void)=>{if(!data)throw new Error('Los datos aún se están cargando.');const draft=structuredClone(data);fn(draft);const saved=await saveData(draft);queryClient.setQueryData(['demo-data'],saved);};
  useEffect(()=>{const onChange=()=>{void refetch();};window.addEventListener(EVENT,onChange);return()=>window.removeEventListener(EVENT,onChange);},[refetch]);
  const allowed = isSuper ? location.startsWith('/admin/') : location.startsWith('/app/') && (!isEmployee || ['/app/dashboard','/app/products','/app/inventory','/app/sales','/app/sales/new'].includes(location));
  useEffect(()=>{if(!isLoading&&!sessionValid){localStorage.removeItem('mi-negocio-session');setSession(null);navigate('/login',{replace:true});}},[isLoading,sessionValid,setSession,navigate]);
  useEffect(()=>{if(!isLoading&&!allowed)navigate(isSuper?'/admin/dashboard':'/app/dashboard',{replace:true});},[allowed,isLoading,isSuper,navigate]);
  const changeRole=(role:string,storeId:string)=>{if(!data)return;let target:Session|undefined;
    if(role==='SUPER_ADMIN'){const superUser=data.users.find(u=>u.platform_role==='SUPER_ADMIN');if(superUser)target={userId:superUser.id,role:'SUPER_ADMIN',storeId};}
    else {const store=storeId||data.stores[0]?.id;const member=data.memberships.find(m=>m.store_id===store&&m.role===role&&m.is_active);if(member)target={userId:member.user_id,role:member.role,storeId:store};}
    if(target){localStorage.setItem('mi-negocio-session',JSON.stringify(target));setSession(target);navigate(target.role==='SUPER_ADMIN'?'/admin/dashboard':'/app/dashboard');announce(`Vista cambiada: ${statusText[target.role]}`);}
  };
  const logout=()=>{localStorage.removeItem('mi-negocio-session');setSession(null);navigate('/login');};
  const reset=async()=>{if(!window.confirm('¿Restablecer todos los datos demo? Se perderán los cambios guardados en este navegador.'))return;const fresh=await resetDemo();queryClient.setQueryData(['demo-data'],fresh);setSession(null);navigate('/login');};
  const navGroups:NavGroup[]=isSuper?adminNav:isEmployee?allNav.map(group=>({...group,links:group.links.filter(([href])=>['/app/dashboard','/app/sales/new','/app/products','/app/inventory','/app/sales'].includes(href))})).filter(group=>group.links.length>0):allNav;
  const heading=isSuper?'Panel de administración':'Panel del local';
  if(isLoading)return <div className="min-h-[100dvh] bg-[#f7f8fc] p-6"><div className="mx-auto max-w-6xl animate-pulse"><div className="h-14 rounded-xl bg-slate-200"/><div className="mt-8 grid grid-cols-2 gap-4 md:grid-cols-4">{[1,2,3,4].map(n=><div key={n} className="h-36 rounded-2xl bg-white"/> )}</div><div className="mt-5 h-80 rounded-2xl bg-white"/></div></div>;
  if(isError||!data)return <div className="grid min-h-[100dvh] place-items-center bg-[#f7f8fc]"><div className="mn-card max-w-md p-8 text-center"><AlertTriangle className="mx-auto text-amber-600"/><h2 className="mt-3 font-bold">No pudimos cargar la demo</h2><p className="mt-2 text-sm text-slate-500">Tus datos locales pueden estar temporalmente inaccesibles.</p><button onClick={()=>void refetch()} className="mn-btn mn-btn-primary mt-5">Reintentar</button></div></div>;
  if(!isSuper&&!currentStore)return <Navigate to="/login" replace/>;
  const body=<Routes>
    <Route path="/" element={<Navigate to={isSuper?'/admin/dashboard':'/app/dashboard'} replace/>}/>
    <Route path="/admin/*" element={isSuper?<AdminPages data={data} commit={commit} announce={announce}/>:<Navigate to="/app/dashboard" replace/>}/>
    <Route path="/app/*" element={!isSuper?<StorePages data={data} commit={commit} session={session} employee={isEmployee} announce={announce}/>:<Navigate to="/admin/dashboard" replace/>}/>
    <Route path="*" element={<div className="mn-card p-8"><h2 className="font-bold">Página no encontrada</h2><Link to={isSuper?'/admin/dashboard':'/app/dashboard'} className="mt-4 inline-flex text-sm font-semibold text-indigo-700">Volver al resumen</Link></div>}/>
  </Routes>;
  return <div className="min-h-[100dvh] bg-[#f7f8fc]">
    {mobileOpen&&<button aria-label="Cerrar navegación" onClick={()=>setMobileOpen(false)} className="fixed inset-0 z-30 bg-slate-950/40 lg:hidden"/>}
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-[254px] flex-col bg-[#20234a] text-slate-100 transition-transform duration-200 lg:translate-x-0 ${mobileOpen?'translate-x-0':'-translate-x-full'}`}>
      <div className="flex h-[76px] items-center gap-3 border-b border-white/10 px-5"><span className="grid h-10 w-10 place-items-center rounded-xl bg-indigo-500 text-white"><BriefcaseBusiness size={20}/></span><div><div className="font-[Manrope] text-[15px] font-extrabold tracking-tight">mi negocio</div><div className="text-[10px] font-medium tracking-wide text-slate-400">{isSuper?'CENTRO DE CONTROL':'GESTIÓN DE LOCAL'}</div></div><button onClick={()=>setMobileOpen(false)} className="ml-auto text-slate-400 lg:hidden"><X size={18}/></button></div>
      <div className="mx-3 mt-5 rounded-xl border border-white/10 bg-white/[.06] p-3"><div className="flex items-center gap-2.5"><span className="grid h-9 w-9 place-items-center rounded-lg bg-indigo-400/20 text-indigo-200">{isSuper?<ShieldCheck size={17}/>:<Store size={17}/>}</span><div className="min-w-0"><div className="truncate text-xs font-bold">{isSuper?'Administración':currentStore?.name}</div><div className="mt-0.5 text-[10px] text-slate-400">{isSuper?'Todos los locales':currentStore?.address.split(',')[1]?.trim()}</div></div></div></div>
      <nav className="flex-1 overflow-y-auto px-3 py-5">{navGroups.map(group=><div key={group.label} className="mb-6"><p className="px-3 pb-2 text-[10px] font-bold uppercase tracking-[.16em] text-slate-500">{group.label}</p><div className="space-y-1">{group.links.map(([href,label,Icon])=><Link key={href as string} to={href as string} onClick={()=>setMobileOpen(false)} data-testid={`link-${String(label).toLowerCase().replaceAll(' ','-')}`} className={`flex items-center gap-3 rounded-lg px-3 py-2.5 text-[13px] font-semibold transition ${location===href?'bg-indigo-500 text-white shadow-sm':'text-slate-300 hover:bg-white/10 hover:text-white'}`}><Icon size={17}/>{label}</Link>)}</div></div>)}</nav>
      <div className="border-t border-white/10 p-4"><div className="flex items-center gap-2.5"><span className="grid h-9 w-9 place-items-center rounded-full bg-indigo-400/20 text-xs font-bold text-indigo-100">{currentUser?.full_name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold">{currentUser?.full_name}</p><p className="text-[10px] text-slate-400">{statusText[session.role]}</p></div><button onClick={logout} title="Cerrar sesión" data-testid="button-logout" className="rounded-md p-1.5 text-slate-400 hover:bg-white/10 hover:text-white"><LogOut size={16}/></button></div></div>
    </aside>
    <div className="min-h-[100dvh] lg:pl-[254px]">
      <header className="sticky top-0 z-20 flex min-h-[76px] items-center justify-between border-b border-slate-200/80 bg-white/90 px-4 backdrop-blur md:px-7"><div className="flex items-center gap-3"><button onClick={()=>setMobileOpen(true)} className="grid h-9 w-9 place-items-center rounded-lg text-slate-600 hover:bg-slate-100 lg:hidden"><Menu size={20}/></button><div className="hidden sm:block"><p className="text-[11px] font-semibold uppercase tracking-wider text-slate-400">{heading}</p><p className="mt-0.5 text-sm font-bold text-slate-800">{isSuper?'Todos tus negocios':currentStore?.name}</p></div></div>
        <div className="flex items-center gap-2">
          <div className="hidden items-center gap-1.5 rounded-lg border border-indigo-100 bg-indigo-50/70 px-2.5 py-2 text-[11px] font-semibold text-indigo-700 sm:flex"><span className="h-1.5 w-1.5 rounded-full bg-emerald-500"/>{isSuper?'Demo global':'Demo local'}</div>
          <div className="relative"><label className="sr-only" htmlFor="demo-switcher">Cambiar vista demo</label><select id="demo-switcher" data-testid="select-demo-switcher" value={`${session.role}|${session.storeId}`} onChange={e=>{const [r,s]=e.target.value.split('|');changeRole(r,s);}} className="h-9 max-w-[155px] rounded-lg border border-slate-200 bg-white px-2 text-xs font-semibold text-slate-700 outline-none focus:border-indigo-400 sm:max-w-[220px]"><option value={`SUPER_ADMIN|${session.storeId}`}>Vista: Superadmin</option>{data.stores.map(store=><optgroup key={store.id} label={store.name}><option value={`STORE_ADMIN|${store.id}`}>Administrador · {store.name}</option><option value={`EMPLOYEE|${store.id}`}>Empleado · {store.name}</option></optgroup>)}</select></div>
          <button data-testid="button-reset-demo" onClick={()=>void reset()} title="Restablecer datos demo" className="grid h-9 w-9 place-items-center rounded-lg border border-slate-200 text-slate-500 hover:border-red-200 hover:bg-red-50 hover:text-red-700"><RotateCcw size={16}/></button>
        </div>
      </header>
      <main className="mx-auto max-w-[1500px] px-4 py-6 md:px-7 md:py-8">{body}<footer className="mt-10 flex flex-wrap items-center justify-between gap-2 border-t border-slate-200/80 py-5 text-[11px] text-slate-400"><span>Mi Negocio · Ambiente de demostración</span><span>Los cambios se guardan en este navegador</span></footer></main>
    </div>{toast&&<Toast text={toast} onClose={()=>setToast('')}/>}
  </div>;
}

type PageProps={data:DemoData;commit:(fn:(draft:DemoData)=>void)=>Promise<void>;announce:(s:string)=>void};
function AdminPages(props:PageProps) {
  return <Routes>
    <Route path="dashboard" element={<AdminDashboard {...props}/>}/>
    <Route path="stores" element={<StoresPage {...props}/>}/>
    <Route path="stores/new" element={<StoresPage {...props} createOnly/>}/>
    <Route path="users" element={<UsersPage {...props}/>}/>
    <Route path="*" element={<Navigate to="/admin/dashboard" replace/>}/>
  </Routes>;
}
function AdminDashboard({data}:PageProps) {
  const active=data.stores.filter(s=>s.status==='ACTIVE').length;
  const totalSales=data.sales.reduce((n,s)=>n+s.total,0);
  const points=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const key=d.toDateString();return {day:d.toLocaleDateString('es-BO',{weekday:'short'}),sales:data.sales.filter(s=>new Date(s.created_at).toDateString()===key).reduce((n,s)=>n+s.total,0)};});
  const activity=[
    ...data.sales.map(s=>({id:s.id,date:s.created_at,label:`Venta registrada · ${data.stores.find(x=>x.id===s.store_id)?.name||'Local'}`,detail:`${data.users.find(x=>x.id===s.sold_by)?.full_name||'Equipo'} · ${money(s.total)}`,icon:CreditCard,tone:'green',status:'Venta'})),
    ...data.stores.map(s=>({id:s.id,date:s.created_at,label:`${s.name} se incorporó`,detail:s.address,icon:Store,tone:s.status==='ACTIVE'?'green':s.status==='SUSPENDED'?'amber':'neutral',status:statusText[s.status]})),
  ].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);
  return <div className="animate-rise"><HeaderTitle title="Centro de control" subtitle="Una mirada completa a los negocios que forman parte de Mi Negocio." action={<Link to="/admin/stores/new" className="mn-btn mn-btn-primary"><Plus size={16}/>Nuevo local</Link>}/>
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
      <Metric label="Locales registrados" value={String(data.stores.length)} meta="En toda la plataforma" icon={Store} tone="indigo" trend="+2 este mes"/>
      <Metric label="Locales activos" value={String(active)} meta={`${data.stores.filter(s=>s.status==='SUSPENDED').length} suspendido · ${data.stores.filter(s=>s.status==='CLOSED').length} cerrados`} icon={CircleCheck} tone="green"/>
      <Metric label="Usuarios" value={String(data.users.length)} meta={`${data.memberships.filter(m=>m.is_active).length} miembros activos`} icon={Users} tone="blue" trend="+12.4%"/>
      <Metric label="Ventas acumuladas" value={money(totalSales)} meta={`${data.sales.length} ventas registradas`} icon={Banknote} tone="amber" trend="+8.6%"/>
    </div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.55fr_1fr]">
      <section className="mn-card p-5 md:p-6"><div className="mb-5 flex items-center justify-between"><div><h2 className="font-[Manrope] text-base font-extrabold">Actividad de ventas</h2><p className="mt-1 text-xs text-slate-500">Ingresos por día en los últimos siete días</p></div><span className="rounded-lg bg-indigo-50 p-2 text-indigo-600"><TrendingUp size={18}/></span></div><div className="h-[245px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={points} margin={{top:8,right:6,left:-20,bottom:0}}><CartesianGrid vertical={false} stroke="#edf0f5"/><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize:11,fill:'#94a3b8'}}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:10,fill:'#94a3b8'}}/><Tooltip formatter={(v)=>money(Number(v))} contentStyle={{borderRadius:12,border:'1px solid #e5e7eb',fontSize:12}}/><Bar dataKey="sales" name="Ventas" fill="#4f46e5" radius={[6,6,0,0]} maxBarSize={34}/></BarChart></ResponsiveContainer></div></section>
      <section className="mn-card p-5 md:p-6"><div className="flex items-center justify-between"><div><h2 className="font-[Manrope] text-base font-extrabold">Actividad reciente</h2><p className="mt-1 text-xs text-slate-500">Movimientos de ventas y locales</p></div><Link to="/admin/stores" className="text-xs font-bold text-indigo-600 hover:text-indigo-800">Ver locales</Link></div><div className="mt-5 space-y-4">{activity.map(item=><div key={item.id} data-testid={`activity-${item.id}`} className="flex items-center gap-3"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-indigo-50 text-indigo-600"><item.icon size={17}/></span><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold text-slate-800">{item.label}</p><p className="truncate text-xs text-slate-500">{item.detail} · {dateFmt(item.date)}</p></div><Badge tone={item.tone}>{item.status}</Badge></div>)}</div></section>
    </div>
    <section className="mn-card mt-5 p-5 md:p-6"><div className="mb-4 flex items-center gap-2"><Activity size={18} className="text-indigo-600"/><h2 className="font-[Manrope] text-base font-extrabold">Accesos rápidos</h2></div><div className="grid gap-3 sm:grid-cols-3"><Link to="/admin/stores" className="flex items-center justify-between rounded-xl border border-slate-200 p-4 hover:border-indigo-200 hover:bg-indigo-50/30"><span><span className="block text-sm font-bold">Gestionar locales</span><span className="mt-1 block text-xs text-slate-500">Estados, datos y administración</span></span><ArrowRight size={17} className="text-indigo-600"/></Link><Link to="/admin/users" className="flex items-center justify-between rounded-xl border border-slate-200 p-4 hover:border-indigo-200 hover:bg-indigo-50/30"><span><span className="block text-sm font-bold">Administrar usuarios</span><span className="mt-1 block text-xs text-slate-500">Roles y acceso a la plataforma</span></span><ArrowRight size={17} className="text-indigo-600"/></Link><Link to="/admin/stores/new" className="flex items-center justify-between rounded-xl border border-slate-200 p-4 hover:border-indigo-200 hover:bg-indigo-50/30"><span><span className="block text-sm font-bold">Registrar un local</span><span className="mt-1 block text-xs text-slate-500">Da de alta un nuevo negocio</span></span><ArrowRight size={17} className="text-indigo-600"/></Link></div></section>
  </div>;
}
function StoresPage({data,commit,announce,createOnly=false}:PageProps&{createOnly?:boolean}) {
  const navigate=useNavigate(); const [search,setSearch]=useState(''); const [filter,setFilter]=useState('ALL');
  const [editor,setEditor]=useState<Local|null|false>(createOnly?false:null); const [detail,setDetail]=useState<Local|null>(null);
  const filtered=data.stores.filter(s=>(filter==='ALL'||s.status===filter)&&`${s.name} ${s.address} ${s.phone}`.toLowerCase().includes(search.toLowerCase()));
  const fields:FieldDef[] = editor===false ? [
    {name:'name',label:'Nombre del local',required:true},{name:'address',label:'Dirección',required:true},{name:'phone',label:'Teléfono',required:true},
    {name:'adminName',label:'Nombre del administrador',required:true},{name:'adminEmail',label:'Correo del administrador',type:'email',required:true},
  ]:[{name:'name',label:'Nombre del local',required:true},{name:'address',label:'Dirección',required:true},{name:'phone',label:'Teléfono',required:true}];
  const save=async(values:Record<string,string>)=>{if(editor===false){if(data.users.some(u=>u.email.toLowerCase()===values.adminEmail.toLowerCase()))throw new Error('Ya existe un usuario con ese correo.');await commit(d=>{const store:Local={id:newId('store'),name:values.name,address:values.address,phone:values.phone,status:'ACTIVE',created_at:new Date().toISOString()};const user:Usuario={id:newId('user'),full_name:values.adminName,email:values.adminEmail,platform_role:'USER',is_active:true,created_at:new Date().toISOString()};d.stores.push(store);d.users.push(user);d.memberships.push({id:newId('member'),store_id:store.id,user_id:user.id,role:'STORE_ADMIN',is_active:true,created_at:new Date().toISOString()});});announce('Local creado y administrador asignado.');navigate('/admin/stores');}
    else if(editor){await commit(d=>{const s=d.stores.find(x=>x.id===editor.id);if(s)Object.assign(s,{name:values.name,address:values.address,phone:values.phone});});announce('Datos del local actualizados.');}};
  const toggle=async(store:Local)=>{const next=store.status==='ACTIVE'?'SUSPENDED':'ACTIVE';if(!window.confirm(`${next==='SUSPENDED'?'¿Suspender':'¿Reactivar'} ${store.name}?`))return;await commit(d=>{const s=d.stores.find(x=>x.id===store.id);if(s)s.status=next;});announce(next==='ACTIVE'?'Local reactivado.':'Local suspendido.');};
  const close=async(store:Local)=>{if(!window.confirm(`¿Cerrar definitivamente ${store.name}? Sus registros demo permanecerán disponibles.`))return;await commit(d=>{const s=d.stores.find(x=>x.id===store.id);if(s)s.status='CLOSED';});announce('Local cerrado.');};
  if(createOnly&&editor===null)return <Navigate to="/admin/stores/new" replace/>;
  return <div className="animate-rise"><HeaderTitle title={createOnly?'Registrar local':'Locales'} subtitle={createOnly?'Crea un espacio de trabajo y asigna su primer administrador.':'Consulta y administra los negocios registrados en la plataforma.'} action={!createOnly&&<button onClick={()=>setEditor(false)} className="mn-btn mn-btn-primary"><Plus size={16}/>Nuevo local</button>}/>
    {createOnly&&<Link to="/admin/stores" className="mb-4 inline-flex items-center gap-2 text-sm font-semibold text-slate-500 hover:text-indigo-700"><ArrowLeft size={16}/>Volver a locales</Link>}
    {!createOnly&&<div className="mb-4 grid gap-3 sm:grid-cols-3"><Metric label="Todos los locales" value={String(data.stores.length)} meta="Registrados en la plataforma" icon={Store}/><Metric label="Activos" value={String(data.stores.filter(s=>s.status==='ACTIVE').length)} meta="Operación habilitada" icon={CircleCheck} tone="green"/><Metric label="Suspendidos" value={String(data.stores.filter(s=>s.status==='SUSPENDED').length)} meta="Acceso temporalmente pausado" icon={Ban} tone="amber"/></div>}
    <section className="mn-card p-4 md:p-5">{!createOnly&&<SearchTools value={search} onChange={setSearch} placeholder="Buscar por local o dirección"><select data-testid="filter-store-status" value={filter} onChange={e=>setFilter(e.target.value)} className="mn-input w-auto min-w-[150px]"><option value="ALL">Todos los estados</option><option value="ACTIVE">Activos</option><option value="SUSPENDED">Suspendidos</option><option value="CLOSED">Cerrados</option></select></SearchTools>}
    {!createOnly&&<Table headers={['Local','Administrador','Miembros','Estado','Alta','Acciones']} empty={!filtered.length}>{filtered.map(store=>{const admin=data.memberships.find(m=>m.store_id===store.id&&m.role==='STORE_ADMIN');const user=data.users.find(u=>u.id===admin?.user_id);return <tr key={store.id} data-testid={`row-store-${store.id}`} className="hover:bg-slate-50/70"><td className="px-4 py-3"><p className="font-bold text-slate-800">{store.name}</p><p className="mt-0.5 text-xs text-slate-500">{store.address}</p></td><td className="px-4 py-3"><p className="text-sm text-slate-700">{user?.full_name||'Sin asignar'}</p><p className="text-xs text-slate-400">{user?.email}</p></td><td className="px-4 py-3 text-slate-600">{data.memberships.filter(m=>m.store_id===store.id&&m.is_active).length}</td><td className="px-4 py-3"><Badge tone={store.status==='ACTIVE'?'green':store.status==='SUSPENDED'?'amber':'neutral'}>{statusText[store.status]}</Badge></td><td className="px-4 py-3 text-xs text-slate-500">{dateFmt(store.created_at)}</td><td className="px-4 py-3"><div className="flex items-center gap-1"><ActionButton id={store.id} label="Consultar local" icon={Eye} onClick={()=>setDetail(store)}/><ActionButton id={store.id} label="Editar local" icon={Pencil} onClick={()=>setEditor(store)}/>{store.status!=='CLOSED'&&<ActionButton id={store.id} label={store.status==='ACTIVE'?'Suspender local':'Reactivar local'} icon={store.status==='ACTIVE'?Ban:CircleCheck} onClick={()=>void toggle(store)}/>}{store.status!=='CLOSED'&&<ActionButton id={store.id} label="Cerrar local" icon={Trash2} variant="danger" onClick={()=>void close(store)}/>}</div></td></tr>;})}</Table>}</section>
    {editor!==null&&<Editor title={editor===false?'Nuevo local':'Editar local'} fields={fields} initial={editor===false?undefined:editor} onClose={()=>setEditor(null)} onSubmit={save} submitText={editor===false?'Crear local':'Guardar local'}/>}
    {detail&&<Modal title="Detalle del local" onClose={()=>setDetail(null)}><div className="space-y-4"><div className="rounded-xl bg-indigo-50 p-4"><div className="flex items-center justify-between"><h3 className="font-bold text-slate-900">{detail.name}</h3><Badge tone={detail.status==='ACTIVE'?'green':detail.status==='SUSPENDED'?'amber':'neutral'}>{statusText[detail.status]}</Badge></div><p className="mt-2 text-sm text-slate-600">{detail.address}</p><p className="mt-1 text-sm text-slate-600">{detail.phone}</p></div>{data.memberships.filter(m=>m.store_id===detail.id).map(m=>{const u=data.users.find(x=>x.id===m.user_id);return <div key={m.id} className="flex items-center justify-between border-b border-slate-100 pb-3"><div><p className="text-sm font-semibold">{u?.full_name}</p><p className="text-xs text-slate-500">{u?.email}</p></div><Badge tone={m.is_active?'green':'red'}>{statusText[m.role]}</Badge></div>})}<p className="text-xs text-slate-400">Registrado el {dateFmt(detail.created_at)}</p></div></Modal>}
  </div>;
}
function UsersPage({data,commit,announce}:PageProps) {
  const [search,setSearch]=useState('');const [state,setState]=useState('ALL');const [role,setRoleFilter]=useState('ALL');const [store,setStore]=useState('ALL');
  const filtered=data.users.filter(user=>{
    const memberships=data.memberships.filter(m=>m.user_id===user.id);
    const names=memberships.map(m=>data.stores.find(s=>s.id===m.store_id)?.name||'').join(' ');
    const roleMatches=role==='ALL'||(role==='SUPER_ADMIN'?user.platform_role==='SUPER_ADMIN':memberships.some(m=>m.role===role));
    const storeMatches=store==='ALL'||memberships.some(m=>m.store_id===store);
    const stateMatches=state==='ALL'||(user.is_active?'ACTIVE':'INACTIVE')===state;
    return roleMatches&&storeMatches&&stateMatches&&`${user.full_name} ${user.email} ${names}`.toLowerCase().includes(search.toLowerCase());
  });
  const rolesFor=(user:Usuario)=>{
    if(user.platform_role==='SUPER_ADMIN')return ['Superadministrador'];
    return [...new Set(data.memberships.filter(m=>m.user_id===user.id).map(m=>statusText[m.role]))];
  };
  const storesFor=(user:Usuario)=>{
    const names=data.memberships.filter(m=>m.user_id===user.id).map(m=>data.stores.find(s=>s.id===m.store_id)?.name).filter(Boolean);
    return [...new Set(names)];
  };
  const toggle=async(user:Usuario)=>{
    if(!window.confirm(`¿${user.is_active?'Desactivar':'Activar'} la cuenta de ${user.full_name}?`))return;
    await commit(d=>{const target=d.users.find(x=>x.id===user.id);if(target)target.is_active=!target.is_active;});
    announce(user.is_active?'Cuenta desactivada.':'Cuenta activada.');
  };
  return <div className="animate-rise"><HeaderTitle title="Usuarios y permisos" subtitle="Controla qué personas pueden entrar y qué rol tienen en cada local."/>
     <section className="mn-card p-4 md:p-5"><SearchTools value={search} onChange={setSearch} placeholder="Buscar persona, correo o local"><select data-testid="filter-user-role" value={role} onChange={e=>setRoleFilter(e.target.value)} className="mn-input w-auto"><option value="ALL">Todos los roles</option><option value="SUPER_ADMIN">Superadministrador</option><option value="STORE_ADMIN">Administrador</option><option value="EMPLOYEE">Empleado</option></select><select data-testid="filter-user-state" value={state} onChange={e=>setState(e.target.value)} className="mn-input w-auto"><option value="ALL">Todos los estados</option><option value="ACTIVE">Activos</option><option value="INACTIVE">Inactivos</option></select><select data-testid="filter-user-store" value={store} onChange={e=>setStore(e.target.value)} className="mn-input w-auto"><option value="ALL">Todos los locales</option>{data.stores.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></SearchTools>
     <Table headers={['Usuario','Rol','Locales','Estado','Acciones']} empty={!filtered.length}>{filtered.map(user=><tr key={user.id} data-testid={`row-user-${user.id}`} className="hover:bg-slate-50/70"><td className="px-4 py-3"><p className="font-bold text-slate-800">{user.full_name}</p><p className="text-xs text-slate-500">{user.email}</p></td><td className="px-4 py-3"><div className="flex flex-wrap gap-1">{rolesFor(user).map(item=><Badge key={item} tone={item==='Superadministrador'?'indigo':'neutral'}>{item}</Badge>)}</div></td><td className="px-4 py-3 text-sm text-slate-700">{storesFor(user).join(', ')||'Plataforma'}</td><td className="px-4 py-3"><Badge tone={user.is_active?'green':'red'}>{user.is_active?'Activo':'Inactivo'}</Badge></td><td className="px-4 py-3"><button data-testid={`button-toggle-user-${user.id}`} onClick={()=>void toggle(user)} className={`mn-btn !h-8 !px-3 text-xs ${user.is_active?'mn-btn-danger':'mn-btn-secondary'}`}>{user.is_active?'Desactivar':'Activar'}</button></td></tr>)}</Table></section>
    <p className="mt-3 text-xs text-slate-400">El superadministrador de plataforma no pertenece a un local y se administra desde el selector de demo.</p>
  </div>;
}

function StorePages({data,commit,session,employee,announce}:{data:DemoData;commit:(fn:(draft:DemoData)=>void)=>Promise<void>;session:Session;employee:boolean;announce:(s:string)=>void}) {
  const store=data.stores.find(s=>s.id===session.storeId)!;
  const scoped={...data,categories:data.categories.filter(x=>x.store_id===store.id),products:data.products.filter(x=>x.store_id===store.id),sales:data.sales.filter(x=>x.store_id===store.id),memberships:data.memberships.filter(x=>x.store_id===store.id)};
  return <Routes>
    <Route path="dashboard" element={<StoreDashboard data={scoped} store={store}/>}/>
    <Route path="products" element={<ProductsPage data={scoped} commit={commit} store={store} employee={employee} announce={announce}/>}/>
    <Route path="categories" element={employee?<Navigate to="/app/dashboard" replace/>:<CategoriesPage data={scoped} commit={commit} store={store} announce={announce}/>}/>
    <Route path="inventory" element={<InventoryPage data={scoped} commit={commit} store={store} employee={employee} announce={announce}/>}/>
    <Route path="employees" element={employee?<Navigate to="/app/dashboard" replace/>:<EmployeesPage data={scoped} commit={commit} store={store} announce={announce}/>}/>
    <Route path="sales" element={<SalesPage data={scoped} store={store}/>}/>
    <Route path="sales/new" element={<NewSalePage data={scoped} commit={commit} store={store} session={session} announce={announce}/>}/>
    <Route path="settings" element={employee?<Navigate to="/app/dashboard" replace/>:<SettingsPage store={store} commit={commit} announce={announce}/>}/>
    <Route path="*" element={<Navigate to="/app/dashboard" replace/>}/>
  </Routes>;
}
function StoreDashboard({data,store}:{data:DemoData;store:Local}) {
  const today=new Date().toDateString();
  const todaySales=data.sales.filter(s=>new Date(s.created_at).toDateString()===today);
  const total=todaySales.reduce((n,s)=>n+s.total,0);
  const low=data.products.filter(p=>p.is_active&&p.stock_quantity<=5);
  const sevenDays=Array.from({length:7},(_,i)=>{const date=new Date();date.setDate(date.getDate()-(6-i));return {day:date.toLocaleDateString('es-BO',{weekday:'short'}),value:data.sales.filter(s=>new Date(s.created_at).toDateString()===date.toDateString()).reduce((n,s)=>n+s.total,0)};});
  const topProducts=data.saleDetails.reduce((acc,d)=>{const product=data.products.find(p=>p.id===d.product_id);if(product)acc.set(product.id,{name:product.name,qty:(acc.get(product.id)?.qty||0)+d.quantity});return acc;},new Map<string,{name:string;qty:number}>());
  const best=[...topProducts.values()].sort((a,b)=>b.qty-a.qty).slice(0,4);
  const latest=[...data.sales].sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,5);
  return <div className="animate-rise"><HeaderTitle title={`Buen día, ${store.name}`} subtitle="Así va el movimiento de tu negocio hoy." action={<Link to="/app/sales/new" className="mn-btn mn-btn-primary"><Plus size={16}/>Registrar venta</Link>}/>
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Ventas de hoy" value={money(total)} meta="Ingresos registrados hoy" icon={Banknote} tone="green" trend="+12.8%"/><Metric label="N.º de ventas" value={String(todaySales.length)} meta="Transacciones de hoy" icon={ShoppingBag} tone="indigo"/><Metric label="Productos activos" value={String(data.products.filter(p=>p.is_active).length)} meta={`${data.categories.length} categorías`} icon={Package} tone="blue"/><Metric label="Alertas de stock" value={String(low.length)} meta={`${data.products.filter(p=>p.stock_quantity===0).length} agotados`} icon={AlertTriangle} tone={low.length?'amber':'green'}/></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.55fr_1fr]"><section className="mn-card p-5 md:p-6"><div className="mb-4 flex items-center justify-between"><div><h2 className="font-[Manrope] font-extrabold">Ventas de los últimos 7 días</h2><p className="mt-1 text-xs text-slate-500">Ingresos diarios en bolivianos</p></div><span className="rounded-lg bg-indigo-50 p-2 text-indigo-600"><BarChart3 size={18}/></span></div><div className="h-[240px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={sevenDays} margin={{top:8,right:5,left:-20,bottom:0}}><CartesianGrid vertical={false} stroke="#edf0f5"/><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize:11,fill:'#94a3b8'}}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:10,fill:'#94a3b8'}}/><Tooltip formatter={v=>money(Number(v))} contentStyle={{borderRadius:12,border:'1px solid #e5e7eb',fontSize:12}}/><Bar dataKey="value" name="Ventas" fill="#4f46e5" radius={[6,6,0,0]} maxBarSize={35}/></BarChart></ResponsiveContainer></div></section>
    <section className="mn-card p-5 md:p-6"><div className="flex items-start justify-between"><div><h2 className="font-[Manrope] font-extrabold">Reponer pronto</h2><p className="mt-1 text-xs text-slate-500">Productos con 5 unidades o menos</p></div><Link to="/app/inventory" className="text-xs font-bold text-indigo-600">Ver inventario</Link></div>{low.length?<div className="mt-4 space-y-3">{low.slice(0,5).map(p=><div key={p.id} className="flex items-center gap-3 rounded-xl border border-slate-100 p-3"><span className={`grid h-9 w-9 place-items-center rounded-lg ${p.stock_quantity===0?'bg-red-50 text-red-600':'bg-amber-50 text-amber-700'}`}><Package size={17}/></span><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{p.name}</p><p className="text-xs text-slate-500">{data.categories.find(c=>c.id===p.category_id)?.name}</p></div><Badge tone={p.stock_quantity===0?'red':'amber'}>{p.stock_quantity===0?'Agotado':`${p.stock_quantity} uds.`}</Badge></div>)}</div>:<Empty title="Todo bajo control" body="No hay productos que necesiten reposición."/>}</section></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1fr_1.4fr]"><section className="mn-card p-5"><div className="flex items-center justify-between"><h2 className="font-[Manrope] font-extrabold">Más vendidos</h2><span className="text-xs text-slate-400">Unidades</span></div>{best.length?<div className="mt-4 space-y-4">{best.map((p,i)=><div key={p.name} className="flex items-center gap-3"><span className="grid h-8 w-8 place-items-center rounded-lg bg-slate-100 text-xs font-bold text-slate-500">{String(i+1).padStart(2,'0')}</span><span className="flex-1 text-sm font-semibold">{p.name}</span><span className="text-sm font-bold text-slate-700">{p.qty}</span></div>)}</div>:<Empty title="Sin ventas aún" body="Los productos más vendidos aparecerán aquí."/>}</section>
    <section className="mn-card p-5"><div className="mb-3 flex items-center justify-between"><h2 className="font-[Manrope] font-extrabold">Últimas ventas</h2><Link to="/app/sales" className="text-xs font-bold text-indigo-600">Ver historial</Link></div><Table headers={['Fecha','Empleado','Total']} empty={!latest.length}>{latest.map(s=><tr key={s.id}><td className="px-3 py-3 text-xs text-slate-600">{dateFmt(s.created_at)} · {timeFmt(s.created_at)}</td><td className="px-3 py-3 text-sm font-medium">{data.users.find(u=>u.id===s.sold_by)?.full_name||'Equipo'}</td><td className="px-3 py-3 text-sm font-bold">{money(s.total)}</td></tr>)}</Table></section></div>
  </div>;
}

function ProductsPage({data,commit,store,employee,announce}:{data:DemoData;commit:(fn:(draft:DemoData)=>void)=>Promise<void>;store:Local;employee:boolean;announce:(s:string)=>void}) {
  const [search,setSearch]=useState('');const [cat,setCat]=useState('ALL');const [active,setActive]=useState('ALL');const [editor,setEditor]=useState<Producto|null|false>(null);
  const products=data.products.filter(p=>(cat==='ALL'||p.category_id===cat)&&(active==='ALL'||p.is_active===(active==='ACTIVE'))&&p.name.toLowerCase().includes(search.toLowerCase()));
  const fields:FieldDef[]=[{name:'name',label:'Nombre del producto',required:true},{name:'category_id',label:'Categoría',options:data.categories.map(c=>({value:c.id,label:c.name})),required:true},{name:'price',label:'Precio (Bs)',type:'number',step:'0.01',min:0,required:true},{name:'stock_quantity',label:'Stock inicial',type:'number',step:'1',min:0,required:true}];
  const save=async(v:Record<string,string>)=>{await commit(d=>{if(editor===false)d.products.push({id:newId('product'),store_id:store.id,category_id:v.category_id,name:v.name,price:Number(v.price),stock_quantity:Number(v.stock_quantity),is_active:true,created_at:new Date().toISOString()});else if(editor){const p=d.products.find(x=>x.id===editor.id);if(p)Object.assign(p,{name:v.name,category_id:v.category_id,price:Number(v.price),stock_quantity:Number(v.stock_quantity)});}});announce(editor===false?'Producto creado.':'Producto actualizado.');};
  const toggle=async(p:Producto)=>{await commit(d=>{const x=d.products.find(y=>y.id===p.id);if(x)x.is_active=!x.is_active;});announce(p.is_active?'Producto desactivado.':'Producto activado.');};
  return <div className="animate-rise"><HeaderTitle title="Productos" subtitle={`${data.products.length} productos en ${store.name}. Mantén precios y disponibilidad al día.`} action={!employee&&<button onClick={()=>setEditor(false)} className="mn-btn mn-btn-primary"><Plus size={16}/>Nuevo producto</button>}/>
    <section className="mn-card p-4 md:p-5"><SearchTools value={search} onChange={setSearch} placeholder="Buscar productos"><select data-testid="filter-product-category" value={cat} onChange={e=>setCat(e.target.value)} className="mn-input w-auto"><option value="ALL">Todas las categorías</option>{data.categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><select data-testid="filter-product-state" value={active} onChange={e=>setActive(e.target.value)} className="mn-input w-auto"><option value="ALL">Todos</option><option value="ACTIVE">Activos</option><option value="INACTIVE">Inactivos</option></select></SearchTools>
      <Table headers={['Producto','Categoría','Precio','Stock','Estado',...(!employee?['Acciones']:[])]} empty={!products.length}>{products.map(p=><tr key={p.id} data-testid={`row-product-${p.id}`} className="hover:bg-slate-50/60"><td className="px-4 py-3 font-semibold text-slate-800">{p.name}</td><td className="px-4 py-3 text-sm text-slate-600">{data.categories.find(c=>c.id===p.category_id)?.name||'—'}</td><td className="px-4 py-3 font-semibold">{money(p.price)}</td><td className="px-4 py-3"><span className={p.stock_quantity<=5?'font-semibold text-amber-700':''}>{p.stock_quantity}</span></td><td className="px-4 py-3"><Badge tone={p.is_active?'green':'neutral'}>{p.is_active?'Activo':'Inactivo'}</Badge></td>{!employee&&<td className="px-4 py-3"><div className="flex gap-1"><ActionButton id={p.id} label="Editar producto" icon={Pencil} onClick={()=>setEditor(p)}/><ActionButton id={p.id} label={p.is_active?'Desactivar producto':'Activar producto'} icon={p.is_active?Ban:CircleCheck} onClick={()=>void toggle(p)}/></div></td>}</tr>)}</Table></section>
    {editor!==null&&<Editor title={editor===false?'Nuevo producto':'Editar producto'} fields={fields} initial={editor===false?undefined:editor} onClose={()=>setEditor(null)} onSubmit={save} submitText={editor===false?'Crear producto':'Guardar producto'}/>}
  </div>;
}
function CategoriesPage({data,commit,store,announce}:PageProps&{store:Local}) {
  const [search,setSearch]=useState('');const [editor,setEditor]=useState<Categoria|null|false>(null);
  const list=data.categories.filter(c=>c.name.toLowerCase().includes(search.toLowerCase()));
  const save=async(v:Record<string,string>)=>{await commit(d=>{if(editor===false)d.categories.push({id:newId('category'),store_id:store.id,name:v.name});else if(editor){const x=d.categories.find(c=>c.id===editor.id);if(x)x.name=v.name;}});announce(editor===false?'Categoría creada.':'Categoría actualizada.');};
  const remove=async(c:Categoria)=>{const linked=data.products.filter(p=>p.category_id===c.id);if(linked.length){window.alert(`No se puede eliminar “${c.name}”: ${linked.length} producto(s) están asociados. Edita o reasigna esos productos antes de resolver la relación.`);return;}if(!window.confirm(`¿Eliminar la categoría ${c.name}?`))return;await commit(d=>{d.categories=d.categories.filter(x=>x.id!==c.id);});announce('Categoría eliminada.');};
  return <div className="animate-rise"><HeaderTitle title="Categorías" subtitle="Ordena el catálogo para que encontrar cada producto sea más fácil." action={<button onClick={()=>setEditor(false)} className="mn-btn mn-btn-primary"><Plus size={16}/>Nueva categoría</button>}/>
    <section className="mn-card p-4 md:p-5"><SearchTools value={search} onChange={setSearch} placeholder="Buscar categoría"/>{list.length?<div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{list.map(c=>{const count=data.products.filter(p=>p.category_id===c.id).length;return <article key={c.id} data-testid={`card-category-${c.id}`} className="rounded-xl border border-slate-200 p-4 transition hover:border-indigo-200 hover:shadow-sm"><div className="flex items-start justify-between"><span className="grid h-10 w-10 place-items-center rounded-xl bg-indigo-50 text-indigo-600"><Tags size={18}/></span><div className="flex gap-1"><ActionButton id={c.id} label="Editar categoría" icon={Pencil} onClick={()=>setEditor(c)}/><ActionButton id={c.id} label="Eliminar categoría" icon={Trash2} variant="danger" onClick={()=>void remove(c)}/></div></div><h3 className="mt-4 font-bold text-slate-800">{c.name}</h3><p className="mt-1 text-xs text-slate-500">{count} {count===1?'producto asociado':'productos asociados'}</p></article>;})}</div>:<Empty title="No encontramos categorías" body="Crea una categoría para mantener el catálogo ordenado."/>}</section>
    {editor!==null&&<Editor title={editor===false?'Nueva categoría':'Editar categoría'} fields={[{name:'name',label:'Nombre de categoría',required:true}]} initial={editor===false?undefined:editor} onClose={()=>setEditor(null)} onSubmit={save} submitText={editor===false?'Crear categoría':'Guardar cambios'}/>}
  </div>;
}
function InventoryPage({data,commit,store,employee,announce}:{data:DemoData;commit:(fn:(draft:DemoData)=>void)=>Promise<void>;store:Local;employee:boolean;announce:(s:string)=>void}) {
  const [search,setSearch]=useState('');const [filter,setFilter]=useState('ALL');const [category,setCategory]=useState('ALL');const [adjust,setAdjust]=useState<Producto|null>(null);
  const products=data.products.filter(p=>(filter==='ALL'||(filter==='OUT'?p.stock_quantity===0:filter==='LOW'?p.stock_quantity>0&&p.stock_quantity<=5:p.stock_quantity>5))&&(category==='ALL'||p.category_id===category)&&p.name.toLowerCase().includes(search.toLowerCase()));
  const adjustStock=async(v:Record<string,string>)=>{const next=Number(v.stock_quantity);if(!Number.isFinite(next)||next<0)throw new Error('El stock no puede ser negativo.');await commit(d=>{const p=d.products.find(x=>x.id===adjust?.id);if(p)p.stock_quantity=next;});announce(`Stock actualizado: ${adjust?.name} ahora tiene ${next} unidades.`);};
  const inventoryValue=data.products.reduce((n,p)=>n+p.price*p.stock_quantity,0);
  return <div className="animate-rise"><HeaderTitle title="Inventario" subtitle={`Revisa existencias de ${store.name} y detecta a tiempo lo que necesita reposición.`}/>
    <div className="mb-4 grid gap-3 sm:grid-cols-3"><Metric label="Unidades en stock" value={String(data.products.reduce((n,p)=>n+p.stock_quantity,0))} meta="Suma de productos disponibles" icon={Package} tone="indigo"/><Metric label="Valor del inventario" value={money(inventoryValue)} meta="Precio actual × existencias" icon={Banknote} tone="green"/><Metric label="Requieren atención" value={String(data.products.filter(p=>p.stock_quantity<=5).length)} meta={`${data.products.filter(p=>p.stock_quantity===0).length} agotados · ${data.products.filter(p=>p.stock_quantity>0&&p.stock_quantity<=5).length} bajos`} icon={AlertTriangle} tone="amber"/></div>
    <section className="mn-card p-4 md:p-5"><SearchTools value={search} onChange={setSearch} placeholder="Buscar producto"><select data-testid="filter-inventory-stock" value={filter} onChange={e=>setFilter(e.target.value)} className="mn-input w-auto"><option value="ALL">Todo el stock</option><option value="LOW">Stock bajo</option><option value="OUT">Agotados</option><option value="AVAILABLE">Disponibles</option></select><select data-testid="filter-inventory-category" value={category} onChange={e=>setCategory(e.target.value)} className="mn-input w-auto"><option value="ALL">Todas las categorías</option>{data.categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></SearchTools>
      <Table headers={['Producto','Categoría','Precio unitario','Existencias','Valor en stock','Alerta',...(!employee?['Acción']:[])]} empty={!products.length}>{products.map(p=><tr key={p.id} data-testid={`row-inventory-${p.id}`}><td className="px-4 py-3 font-semibold">{p.name}</td><td className="px-4 py-3 text-slate-600">{data.categories.find(c=>c.id===p.category_id)?.name}</td><td className="px-4 py-3">{money(p.price)}</td><td className="px-4 py-3 font-bold">{p.stock_quantity}</td><td className="px-4 py-3">{money(p.stock_quantity*p.price)}</td><td className="px-4 py-3">{p.stock_quantity===0?<Badge tone="red">Agotado</Badge>:p.stock_quantity<=5?<Badge tone="amber">Stock bajo</Badge>:<Badge tone="green">Normal</Badge>}</td>{!employee&&<td className="px-4 py-3"><button data-testid={`button-adjust-stock-${p.id}`} onClick={()=>setAdjust(p)} className="mn-btn mn-btn-secondary !h-8 !px-3 text-xs"><SlidersHorizontal size={14}/>Ajustar</button></td>}</tr>)}</Table></section>
    {adjust&&<Editor title={`Ajustar existencias · ${adjust.name}`} fields={[{name:'stock_quantity',label:'Nueva cantidad en stock',type:'number',min:0,required:true}]} initial={{stock_quantity:adjust.stock_quantity}} onClose={()=>setAdjust(null)} onSubmit={adjustStock} submitText="Aplicar ajuste"/>}
    <p className="mt-3 text-xs text-slate-400">{employee?'Vista de solo lectura para empleados.':'Los ajustes se simulan localmente y quedan registrados en esta demo.'}</p>
  </div>;
}
function EmployeesPage({data,commit,store,announce}:PageProps&{store:Local}) {
  const [search,setSearch]=useState('');const [filter,setFilter]=useState('ALL');const [editor,setEditor]=useState<MiembroLocal|null|false>(null);
  const list=data.memberships.filter(m=>m.role!=='STORE_ADMIN').map(m=>({m,u:data.users.find(u=>u.id===m.user_id)})).filter(x=>x.u&&(filter==='ALL'||(x.m.is_active?'ACTIVE':'INACTIVE')===filter)&&`${x.u?.full_name} ${x.u?.email}`.toLowerCase().includes(search.toLowerCase()));
  const save=async(v:Record<string,string>)=>{if(editor===false){if(data.users.some(u=>u.email.toLowerCase()===v.email.toLowerCase()))throw new Error('Ya existe un usuario con ese correo.');await commit(d=>{const user:Usuario={id:newId('user'),full_name:v.full_name,email:v.email,platform_role:'USER',is_active:true,created_at:new Date().toISOString()};d.users.push(user);d.memberships.push({id:newId('member'),store_id:store.id,user_id:user.id,role:'EMPLOYEE',is_active:true,created_at:new Date().toISOString()});});announce('Empleado agregado al equipo.');}
    else if(editor){await commit(d=>{const u=d.users.find(x=>x.id===editor.user_id);if(u)Object.assign(u,{full_name:v.full_name,email:v.email});});announce('Datos del empleado actualizados.');}};
  const toggle=async(m:MiembroLocal,name:string)=>{if(!window.confirm(`${m.is_active?'¿Desactivar':'¿Activar'} el acceso de ${name}?`))return;await commit(d=>{const x=d.memberships.find(a=>a.id===m.id);if(x)x.is_active=!x.is_active;const user=d.users.find(a=>a.id===m.user_id);if(user)user.is_active=!m.is_active;});announce(m.is_active?'Acceso del empleado desactivado.':'Empleado activado.');};
  const editedUser=editor!==null&&editor!==false?data.users.find(u=>u.id===editor.user_id):undefined;
  return <div className="animate-rise"><HeaderTitle title="Empleados" subtitle={`Gestiona el equipo de ${store.name} y sus permisos de acceso.`} action={<button onClick={()=>setEditor(false)} className="mn-btn mn-btn-primary"><Plus size={16}/>Nuevo empleado</button>}/>
    <section className="mn-card p-4 md:p-5"><SearchTools value={search} onChange={setSearch} placeholder="Buscar por nombre o correo"><select data-testid="filter-employee-state" value={filter} onChange={e=>setFilter(e.target.value)} className="mn-input w-auto"><option value="ALL">Todos los estados</option><option value="ACTIVE">Activos</option><option value="INACTIVE">Inactivos</option></select></SearchTools><Table headers={['Empleado','Rol','Estado','Fecha de alta','Acciones']} empty={!list.length}>{list.map(({m,u})=><tr key={m.id} data-testid={`row-employee-${u?.id}`}><td className="px-4 py-3"><p className="font-semibold">{u?.full_name}</p><p className="text-xs text-slate-500">{u?.email}</p></td><td className="px-4 py-3"><Badge tone="indigo">Empleado</Badge></td><td className="px-4 py-3"><Badge tone={m.is_active?'green':'red'}>{m.is_active?'Activo':'Inactivo'}</Badge></td><td className="px-4 py-3 text-xs text-slate-500">{dateFmt(m.created_at)}</td><td className="px-4 py-3"><div className="flex gap-1"><ActionButton id={m.id} label="Editar empleado" icon={Pencil} onClick={()=>setEditor(m)}/><button data-testid={`button-toggle-employee-${m.id}`} onClick={()=>void toggle(m,u?.full_name||'el empleado')} className={`mn-btn !h-8 !px-3 text-xs ${m.is_active?'mn-btn-danger':'mn-btn-secondary'}`}>{m.is_active?'Desactivar':'Activar'}</button></div></td></tr>)}</Table></section>
    {editor!==null&&<Editor title={editor===false?'Agregar empleado':'Editar empleado'} fields={[{name:'full_name',label:'Nombre completo',required:true},{name:'email',label:'Correo electrónico',type:'email',required:true}]} initial={editedUser} onClose={()=>setEditor(null)} onSubmit={save} submitText={editor===false?'Agregar empleado':'Guardar cambios'}/>}
    <p className="mt-3 text-xs text-slate-400">Los empleados pueden registrar ventas y consultar productos e inventario de este local.</p>
  </div>;
}
function SettingsPage({store,commit,announce}:{store:Local;commit:(fn:(draft:DemoData)=>void)=>Promise<void>;announce:(s:string)=>void}) {
  const [editing,setEditing]=useState(false);
  const save=async(v:Record<string,string>)=>{await commit(d=>{const s=d.stores.find(x=>x.id===store.id);if(s)Object.assign(s,{name:v.name,address:v.address,phone:v.phone});});announce('Datos del local guardados.');};
  return <div className="animate-rise"><HeaderTitle title="Configuración" subtitle="Información y datos de contacto de tu local."/><section className="mn-card max-w-3xl p-5 md:p-7"><div className="flex items-start gap-4 border-b border-slate-100 pb-5"><span className="grid h-12 w-12 place-items-center rounded-xl bg-indigo-50 text-indigo-600"><Store size={22}/></span><div className="flex-1"><h2 className="font-[Manrope] text-lg font-extrabold">{store.name}</h2><p className="mt-1 text-sm text-slate-500">Local activo en Mi Negocio</p></div><button onClick={()=>setEditing(true)} className="mn-btn mn-btn-secondary !h-9"><Pencil size={15}/>Editar</button></div><div className="grid gap-5 pt-5 sm:grid-cols-2"><div><p className="text-xs font-semibold uppercase tracking-wide text-slate-400">Nombre comercial</p><p className="mt-1.5 text-sm font-semibold">{store.name}</p></div><div><p className="text-xs font-semibold uppercase tracking-wide text-slate-400">Teléfono</p><p className="mt-1.5 text-sm font-semibold">{store.phone}</p></div><div className="sm:col-span-2"><p className="text-xs font-semibold uppercase tracking-wide text-slate-400">Dirección</p><p className="mt-1.5 text-sm font-semibold">{store.address}</p></div></div><div className="mt-6 rounded-xl bg-slate-50 p-4 text-xs leading-5 text-slate-500"><span className="font-bold text-slate-700">Consejo:</span> Mantén estos datos actualizados para que tu equipo pueda identificar fácilmente el local asociado a sus ventas.</div></section>{editing&&<Editor title="Editar información del local" fields={[{name:'name',label:'Nombre comercial',required:true},{name:'address',label:'Dirección',required:true},{name:'phone',label:'Teléfono',required:true}]} initial={store} onClose={()=>setEditing(false)} onSubmit={save}/>}</div>;
}
function SalesPage({data,store}:{data:DemoData;store:Local}) {
  const [search,setSearch]=useState('');const [employee,setEmployee]=useState('ALL');const [from,setFrom]=useState('');const [to,setTo]=useState('');const [detail,setDetail]=useState<Venta|null>(null);
  const staff=data.memberships.filter(m=>m.is_active).map(m=>data.users.find(u=>u.id===m.user_id)).filter(Boolean);
  const list=[...data.sales].filter(s=>(employee==='ALL'||s.sold_by===employee)&&(!from||new Date(s.created_at)>=new Date(`${from}T00:00:00`))&&(!to||new Date(s.created_at)<=new Date(`${to}T23:59:59`))&&`${s.id} ${data.users.find(u=>u.id===s.sold_by)?.full_name||''}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.created_at.localeCompare(a.created_at));
  const detailLines=detail?data.saleDetails.filter(d=>d.sale_id===detail.id):[];
  return <div className="animate-rise"><HeaderTitle title="Historial de ventas" subtitle={`Consulta los movimientos y recibos ficticios de ${store.name}.`} action={<Link to="/app/sales/new" className="mn-btn mn-btn-primary"><Plus size={16}/>Nueva venta</Link>}/>
    <section className="mn-card p-4 md:p-5"><SearchTools value={search} onChange={setSearch} placeholder="Buscar por código o empleado"><select data-testid="filter-sales-employee" value={employee} onChange={e=>setEmployee(e.target.value)} className="mn-input w-auto"><option value="ALL">Todo el equipo</option>{staff.map(u=><option key={u?.id} value={u?.id}>{u?.full_name}</option>)}</select><div className="flex items-center gap-2"><label className="sr-only" htmlFor="sales-from">Desde</label><input id="sales-from" data-testid="filter-sales-from" aria-label="Desde" type="date" value={from} onChange={e=>setFrom(e.target.value)} className="mn-input w-auto"/><span className="text-xs text-slate-400">a</span><label className="sr-only" htmlFor="sales-to">Hasta</label><input id="sales-to" data-testid="filter-sales-to" aria-label="Hasta" type="date" value={to} onChange={e=>setTo(e.target.value)} className="mn-input w-auto"/></div></SearchTools>
    <Table headers={['N.º de venta','Fecha y hora','Empleado','Productos','Total','Detalle']} empty={!list.length}>{list.map(s=>{const lineCount=data.saleDetails.filter(d=>d.sale_id===s.id).reduce((n,d)=>n+d.quantity,0);return <tr key={s.id} data-testid={`row-sale-${s.id}`} className="hover:bg-slate-50/60"><td className="px-4 py-3 font-mono text-xs font-semibold text-indigo-700">#{s.id.slice(-6).toUpperCase()}</td><td className="px-4 py-3 text-xs text-slate-600">{dateFmt(s.created_at)} · {timeFmt(s.created_at)}</td><td className="px-4 py-3 text-sm">{data.users.find(u=>u.id===s.sold_by)?.full_name||'Equipo'}</td><td className="px-4 py-3 text-sm text-slate-600">{lineCount} unidades</td><td className="px-4 py-3 font-bold">{money(s.total)}</td><td className="px-4 py-3"><button data-testid={`button-sale-detail-${s.id}`} onClick={()=>setDetail(s)} className="mn-btn mn-btn-secondary !h-8 !px-3 text-xs"><Eye size={14}/>Ver recibo</button></td></tr>;})}</Table></section>
    <div className="mt-3 flex items-center justify-between text-xs text-slate-400"><span>{list.length} ventas</span><span>Total filtrado: {money(list.reduce((n,s)=>n+s.total,0))}</span></div>
    {detail&&<Modal title={`Recibo de venta #${detail.id.slice(-6).toUpperCase()}`} onClose={()=>setDetail(null)}><Receipt sale={detail} lines={detailLines} data={data} store={store}/></Modal>}
  </div>;
}
type CartItem={productId:string;quantity:number};
function NewSalePage({data,commit,store,session,announce}:{data:DemoData;commit:(fn:(draft:DemoData)=>void)=>Promise<void>;store:Local;session:Session;announce:(s:string)=>void}) {
  const [search,setSearch]=useState('');const [category,setCategory]=useState('ALL');const [cart,setCart]=useState<CartItem[]>([]);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [receipt,setReceipt]=useState<{sale:Venta;lines:DemoData['saleDetails']}|null>(null);
  const items=data.products.filter(p=>p.is_active&&(category==='ALL'||p.category_id===category)&&p.name.toLowerCase().includes(search.toLowerCase()));
  const cartLines=cart.map(c=>({ ...c, product:data.products.find(p=>p.id===c.productId)! })).filter(x=>x.product);
  const total=cartLines.reduce((n,x)=>n+x.product.price*x.quantity,0);
  const add=(p:Producto)=>{setError('');setCart(prev=>{const old=prev.find(x=>x.productId===p.id);if((old?.quantity||0)>=p.stock_quantity){setError(`Stock insuficiente para ${p.name}.`);return prev;}return old?prev.map(x=>x.productId===p.id?{...x,quantity:x.quantity+1}:x):[...prev,{productId:p.id,quantity:1}];});};
  const setQty=(product:Producto,qty:number)=>{if(qty>product.stock_quantity){setError(`Solo hay ${product.stock_quantity} unidades de ${product.name}.`);return;}setError('');if(qty<=0)setCart(prev=>prev.filter(x=>x.productId!==product.id));else setCart(prev=>prev.map(x=>x.productId===product.id?{...x,quantity:qty}:x));};
  const confirm=async()=>{setError('');if(!cartLines.length){setError('Agrega al menos un producto para registrar la venta.');return;}const shortage=cartLines.find(x=>x.quantity>x.product.stock_quantity);if(shortage){setError(`Stock insuficiente para ${shortage.product.name}.`);return;}setBusy(true);
    const saleId=newId('sale');const created_at=new Date().toISOString();const sale:Venta={id:saleId,store_id:store.id,sold_by:session.userId,total,created_at};const lines=cartLines.map(x=>({id:newId('line'),sale_id:saleId,store_id:store.id,product_id:x.product.id,quantity:x.quantity,unit_price:x.product.price}));
    try{await commit(d=>{for(const line of lines){const product=d.products.find(p=>p.id===line.product_id);if(!product||product.stock_quantity<line.quantity)throw new Error(`Stock insuficiente para ${product?.name||'un producto'}.`);product.stock_quantity-=line.quantity;}d.sales.push(sale);d.saleDetails.push(...lines);});setReceipt({sale,lines});setCart([]);announce('Venta registrada y stock actualizado.');}catch(e){setError(e instanceof Error?e.message:'No se pudo registrar la venta.');}finally{setBusy(false);}
  };
  return <div className="animate-rise"><HeaderTitle title="Nueva venta" subtitle={`Registra una venta en ${store.name}; el inventario se actualizará al confirmar.`} action={<Link to="/app/sales" className="mn-btn mn-btn-secondary"><ArrowLeft size={15}/>Historial</Link>}/>
    <div className="grid items-start gap-5 xl:grid-cols-[1.55fr_.85fr]"><section className="mn-card p-4 md:p-5"><div className="mb-4 flex flex-wrap gap-2"><div className="relative min-w-[200px] flex-1"><Search size={16} className="absolute left-3 top-3 text-slate-400"/><input data-testid="input-sale-search" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar productos para agregar" className="mn-input pl-9"/></div><select data-testid="filter-sale-category" value={category} onChange={e=>setCategory(e.target.value)} className="mn-input w-auto min-w-[150px]"><option value="ALL">Todas las categorías</option>{data.categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></div>
      {items.length?<div className="grid gap-3 sm:grid-cols-2">{items.map(p=>{const qty=cart.find(x=>x.productId===p.id)?.quantity||0;return <article key={p.id} className="flex items-center gap-3 rounded-xl border border-slate-200 p-3 transition hover:border-indigo-200"><span className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-indigo-50 text-indigo-600"><Package size={18}/></span><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold text-slate-800">{p.name}</p><p className="text-xs text-slate-500">{data.categories.find(c=>c.id===p.category_id)?.name} · Stock {p.stock_quantity}</p><p className="mt-1 text-sm font-extrabold text-indigo-700">{money(p.price)}</p></div><button data-testid={`button-add-${p.id}`} disabled={p.stock_quantity===0||qty>=p.stock_quantity} onClick={()=>add(p)} className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-indigo-600 text-white transition hover:bg-indigo-700 disabled:bg-slate-200 disabled:text-slate-400"><Plus size={17}/></button></article>;})}</div>:<Empty title="No hay productos disponibles" body="Prueba con otra búsqueda o cambia la categoría."/>}
    </section>
    <aside className="mn-card p-4 md:sticky md:top-[96px] md:p-5"><div className="mb-4 flex items-center justify-between"><div><h2 className="font-[Manrope] text-lg font-extrabold">Detalle de venta</h2><p className="mt-1 text-xs text-slate-500">{cart.length} productos distintos</p></div><span className="grid h-10 w-10 place-items-center rounded-xl bg-indigo-50 text-indigo-600"><ShoppingCart size={19}/></span></div>
      {cartLines.length?<div className="max-h-[360px] space-y-3 overflow-y-auto pr-1">{cartLines.map(line=><div key={line.productId} className="rounded-xl border border-slate-100 p-3"><div className="flex items-start justify-between gap-2"><div className="min-w-0"><p className="truncate text-sm font-bold">{line.product.name}</p><p className="text-xs text-slate-500">{money(line.product.price)} c/u</p></div><button data-testid={`button-remove-${line.product.id}`} aria-label={`Quitar ${line.product.name}`} onClick={()=>setQty(line.product,0)} className="text-slate-400 hover:text-red-600"><Trash2 size={16}/></button></div><div className="mt-3 flex items-center justify-between"><div className="flex items-center gap-2"><button aria-label="Disminuir cantidad" onClick={()=>setQty(line.product,line.quantity-1)} className="grid h-7 w-7 place-items-center rounded-md border border-slate-200 text-slate-600">−</button><input data-testid={`input-quantity-${line.product.id}`} aria-label={`Cantidad de ${line.product.name}`} type="number" min="1" max={line.product.stock_quantity} value={line.quantity} onChange={e=>setQty(line.product,Number(e.target.value))} className="h-7 w-12 rounded border border-slate-200 text-center text-xs font-semibold"/><button aria-label="Aumentar cantidad" disabled={line.quantity>=line.product.stock_quantity} onClick={()=>setQty(line.product,line.quantity+1)} className="grid h-7 w-7 place-items-center rounded-md border border-slate-200 text-slate-600 disabled:opacity-40">+</button></div><span className="text-sm font-bold">{money(line.product.price*line.quantity)}</span></div></div>)}</div>:<div className="flex min-h-44 flex-col items-center justify-center rounded-xl border border-dashed border-slate-200 px-4 text-center"><ShoppingCart size={24} className="text-slate-300"/><p className="mt-3 text-sm font-semibold text-slate-700">Aún no hay productos</p><p className="mt-1 text-xs text-slate-400">Agrega artículos desde el catálogo.</p></div>}
      <div className="mt-4 border-t border-slate-100 pt-4"><div className="flex justify-between text-sm text-slate-500"><span>Subtotal</span><span>{money(total)}</span></div><div className="mt-2 flex justify-between text-lg font-extrabold text-slate-900"><span>Total</span><span data-testid="text-sale-total">{money(total)}</span></div>{error&&<p data-testid="text-sale-error" className="mt-3 rounded-lg bg-red-50 px-3 py-2 text-xs leading-5 text-red-700">{error}</p>}<button data-testid="button-confirm-sale" disabled={busy||cart.length===0} onClick={()=>void confirm()} className="mn-btn mn-btn-primary mt-4 w-full !h-11"><Check size={17}/>{busy?'Guardando venta…':'Confirmar venta'}</button><p className="mt-2 text-center text-[10px] text-slate-400">Al confirmar se descontará el stock disponible.</p></div>
    </aside></div>
    {receipt&&<Modal title="Venta registrada" onClose={()=>setReceipt(null)}><Receipt sale={receipt.sale} lines={receipt.lines} data={data} store={store} onDone={()=>setReceipt(null)}/></Modal>}
  </div>;
}
function Receipt({sale,lines,data,store,onDone}:{sale:Venta;lines:DemoData['saleDetails'];data:DemoData;store:Local;onDone?:()=>void}) {
  return <div><div className="rounded-xl border border-slate-200 p-5 text-center"><div className="mx-auto grid h-12 w-12 place-items-center rounded-full bg-emerald-50 text-emerald-600"><Check size={23}/></div><p className="mt-3 text-xs font-bold uppercase tracking-[.15em] text-slate-400">Recibo ficticio</p><h3 className="mt-1 font-[Manrope] text-xl font-extrabold">{store.name}</h3><p className="mt-1 text-xs text-slate-500">{store.address}</p><div className="my-4 border-y border-dashed border-slate-200 py-3 text-left text-xs text-slate-500"><div className="flex justify-between"><span>Venta</span><strong className="font-mono text-slate-700">#{sale.id.slice(-6).toUpperCase()}</strong></div><div className="mt-1 flex justify-between"><span>Fecha</span><span>{dateFmt(sale.created_at)} · {timeFmt(sale.created_at)}</span></div><div className="mt-1 flex justify-between"><span>Atendió</span><span>{data.users.find(u=>u.id===sale.sold_by)?.full_name||'Equipo'}</span></div></div><div className="space-y-2 text-left">{lines.map(line=>{const product=data.products.find(p=>p.id===line.product_id);return <div key={line.id} className="flex justify-between gap-3 text-xs"><span>{line.quantity} × {product?.name}</span><span className="font-semibold">{money(line.quantity*line.unit_price)}</span></div>;})}</div><div className="mt-4 flex justify-between border-t border-slate-200 pt-3 font-extrabold"><span>Total pagado</span><span>{money(sale.total)}</span></div><p className="mt-4 text-[10px] text-slate-400">Comprobante de demostración · No válido como factura</p></div><div className="mt-4 flex justify-end gap-2"><button onClick={()=>window.print()} className="mn-btn mn-btn-secondary"><FileText size={15}/>Imprimir recibo</button>{onDone&&<button onClick={onDone} className="mn-btn mn-btn-primary">Listo</button>}</div></div>;
}
